  python3 -c 'import re,sys; m=re.search(r"gitleaks/gitleaks\n\s+rev: v8\.(\d+)\.", open(sys.argv[1]).read()); sys.exit(0 if m and int(m.group(1))>=24 else 1)' "$d/.pre-commit-config.yaml" \
