    gstep=$(python3 - "$qg" <<'PY2'
import re, sys, textwrap
t = open(sys.argv[1], encoding="utf-8").read()
a = t.find("- name: Download gitleaks"); b = t.find("\n      - name:", a + 1); step = t[a:b] if a >= 0 else ""
