sys.exit(0 if d.get("extend",{}).get("useDefault") is True and all(p.startswith(("^","(^|/)")) for p in ps) and not any("tests/" in p or "mock-services/" in p for p in ps) else 1)' "$d/.gitleaks.toml" \
