  echo 'repos: []' > .pre-commit-config.yaml
  [ "$(bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: config and no hook -> HOOKS OFF" || bad "check: config and no hook was not stopped"
  mkdir -p sub && [ "$(cd sub && bash -c "$gate_line")" = "HOOKS OFF" ] && ok "check: run from a subfolder -> HOOKS OFF" || bad "check: missed from a subfolder"
  printf '#!/bin/sh\nexit 0\n' > .git/hooks/pre-commit; chmod +x .git/hooks/pre-commit
