# "Move to work" and "Bring work level after a ship", run as written (git-operations.md, The branch)
blk() { python3 - "$GO" "$1" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"\*\*" + re.escape(sys.argv[2]) + r".*?```bash\n(.*?)\n```", t, re.S)
print(m.group(1) if m else "")
PY
}
mv_blk=$(blk 'Move to `work`.**'); lv_blk=$(blk 'Bring `work` level after a ship.**')
repo() { rm -rf "$1"; git init -q -b main "$1"; (cd "$1" && git config user.name t && git config user.email t@example.invalid && echo a > a.txt && git add a.txt && git commit -q -m one); }
if [ -z "$mv_blk" ] || [ -z "$lv_blk" ]; then bad "the move and level blocks aren't in git-operations.md"; else
  repo "$T/mv1"; cd "$T/mv1"; echo unsaved >> a.txt
  [ "$(bash -c "$mv_blk")" = MOVED ] && [ "$(git branch --show-current)" = work ] && grep -q unsaved a.txt && ok "move: on main -> on work, unsaved changes kept" || bad "move: didn't move to work with the changes"
  [ -z "$(bash -c "$mv_blk")" ] && ok "move: already on work -> nothing" || bad "move: ran again on work"
  repo "$T/mv2"; cd "$T/mv2"; git branch work; echo b >> a.txt; git commit -qam two
  out=$(bash -c "$mv_blk"); [ "$out" = "WORK DIFFERS" ] && [ "$(git branch --show-current)" = main ] && ok "move: a work branch without main's head -> WORK DIFFERS, stays on main" || bad "move: switched to a work branch that lacks main's saves ($out)"
  git branch -f work main; [ "$(bash -c "$mv_blk")" = MOVED ] && [ "$(git branch --show-current)" = work ] && ok "move: a work branch that has main's head -> switched to it" || bad "move: didn't switch to a work branch holding main's head"
  # level: a GitHub stand-in, then the three cases
  git init -q --bare "$T/origin.git"; repo "$T/lv"; cd "$T/lv"; git remote add origin "$T/origin.git"; git push -q origin main; git remote set-head origin main
  git switch -q -c work
  [ -z "$(bash -c "$lv_blk")" ] && ok "level: work level with main -> nothing" || bad "level: acted on a level branch"
  echo feature >> a.txt; git commit -qam feature
  [ "$(bash -c "$lv_blk")" = "UNSHIPPED SAVES" ] && [ "$(git log -1 --format=%s)" = feature ] && ok "level: work holds an unshipped save -> left as it is" || bad "level: an unshipped save was touched"
  # the pull request is squash-merged on GitHub: main gets one new save with work's change
  git clone -q "$T/origin.git" "$T/gh" && (cd "$T/gh" && git config user.name t && git config user.email t@example.invalid)
