  cd "$OLDROOT"
fi

# --- Part 3: real behaviour ---------------------------------------------------------------------------
skip3() { echo "SKIPPED  Part 3 (real saves through the scaffold's hooks): $1 -- NOT PROVEN on this machine"; [ -z "${CI:-}" ] || bad "Part 3 skipped in CI: $1"; }
block41=$(python3 - "$MK" <<'PY'
import re, sys
t = open(sys.argv[1], encoding="utf-8").read()
m = re.search(r"^41c\. .*?```bash\n(.*?)\n```", t, re.S | re.M)
print(m.group(1) if m else "")
PY
)
key() { python3 -c 'import secrets,string; a=string.ascii_letters+string.digits; print("gh"+"p_"+"".join(secrets.choice(a) for _ in range(36)))'; }
newapp() {  # a throwaway copy of the scaffold with its placeholders filled, git started, an identity set
  rm -rf "$1"; mkdir -p "$1"
